using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 readonly DataGridView[] exposureAuditGrids=new DataGridView[8],topographicAuditGrids=new DataGridView[8];
 static DataGridView AuditGrid(){var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};foreach(string name in new[]{"Check / parameter","Value","Decision / basis"})grid.Columns.Add(name,name);grid.Columns[0].FillWeight=27;grid.Columns[1].FillWeight=25;grid.Columns[2].FillWeight=48;GridAppearance.Apply(grid);return grid;}
 void AddAuditPage(){var page=new TabPage("Exposure & Kzt audit");var directions=new NavigationTabs{Dock=DockStyle.Fill};for(int i=0;i<8;i++){var direction=new TabPage(WindAssessment.Directions[i]);var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};split.RowStyles.Add(new RowStyle(SizeType.Absolute,32));split.RowStyles.Add(new RowStyle(SizeType.Percent,50));split.RowStyles.Add(new RowStyle(SizeType.Absolute,32));split.RowStyles.Add(new RowStyle(SizeType.Percent,50));exposureAuditGrids[i]=AuditGrid();topographicAuditGrids[i]=AuditGrid();split.Controls.Add(new Label{Text="Mapped surface roughness and exposure decision",Dock=DockStyle.Fill,Font=ModernUi.Strong},0,0);split.Controls.Add(exposureAuditGrids[i],0,1);split.Controls.Add(new Label{Text="Topographic factor — criteria and substitution",Dock=DockStyle.Fill,Font=ModernUi.Strong},0,2);split.Controls.Add(topographicAuditGrids[i],0,3);direction.Controls.Add(split);directions.TabPages.Add(direction);}page.Controls.Add(directions);AddResultPage(page);}
 void UpdateAuditViews(List<WindDirection> values){for(int i=0;i<8;i++){if(exposureAuditGrids[i]==null)continue;exposureAuditGrids[i].Rows.Clear();topographicAuditGrids[i].Rows.Clear();if(values==null)continue;var data=values[i];if(data.ExposureAudit!=null){foreach(var row in data.ExposureAudit.Checks)exposureAuditGrids[i].Rows.Add(row.Cast<object>().ToArray());exposureAuditGrids[i].Rows.Add("Explanation",data.Exposure,data.ExposureAudit.Reason);}foreach(var row in data.TopographicChecks)topographicAuditGrids[i].Rows.Add(row.Cast<object>().ToArray());topographicAuditGrids[i].Rows.Add("Explanation",F(data.Kzt),data.TopographicReason);}}
}
}
